//! Generated bytes for the loader.
//!
//! Every refusal rule already has a hand-written case; these check the rules
//! nobody wrote — a truncated table, a length field that points past the end, a
//! flipped bit in a header. The loader may refuse any of them, but a refusal is
//! a `Result`, never a panic: the input comes from a file a program wrote.

use cyberspine_binfmt::image::Image;
use cyberspine_binfmt::load::VerifiedImage;
use cyberspine_isa::{Insn, OpCode};
use cyberspine_rig::Name;
use proptest::prelude::*;

fn image_bytes() -> Vec<u8> {
    let mut image = Image::new(vec![Insn::new(OpCode::Yield), Insn::new(OpCode::Halt)]);
    image.push_muscle(&Name::new("m0").expect("a legal name"));
    image.to_bytes()
}

proptest! {
    #[test]
    fn any_bytes_are_refused_or_loaded(bytes in proptest::collection::vec(any::<u8>(), 0..512)) {
        let _ = VerifiedImage::from_bytes(&bytes);
    }

    #[test]
    fn a_mutated_image_is_refused_or_loaded(
        position in 0usize..4096,
        mask in 1u8..=255,
    ) {
        let mut bytes = image_bytes();
        let index = position % bytes.len();
        bytes[index] ^= mask;
        let _ = VerifiedImage::from_bytes(&bytes);
    }
}
